				{
					// lastSelectedOption is only valid when interacting with multi-patch farmers.
					if (patch.getPatchNumber() == -1 || patch.getPatchNumber() == lastSelectedOption)
					{
						p = patch;
					}
				}
			}
		}
		return p;
	}
}

